const locs = $('Load Locations').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

// Plausible physical ranges (ug/m3, AQI). Values outside are treated as invalid and stored as NULL.
const LIMITS = {
  pm2_5: [0, 1000], pm10: [0, 2000], nitrogen_dioxide: [0, 2000], ozone: [0, 1000],
  sulphur_dioxide: [0, 2000], carbon_monoxide: [0, 100000], us_aqi: [0, 500]
};
const METRICS = Object.keys(LIMITS);
const now = Date.now();

const byKey = new Map();
const failures = [];
let invalid = 0;

responses.forEach((res, i) => {
  const loc = locs[i];            // HTTP responses keep the order of the locations
  if (!loc) return;
  const h = res && res.hourly;
  if (!res || res.error || !h || !Array.isArray(h.time)) {
    const why = (res && (res.reason || (typeof res.error === 'string' ? res.error : (res.error && res.error.message)))) || 'no hourly data in response';
    failures.push(loc.name + ': ' + String(why).slice(0, 120));
    return;
  }
  h.time.forEach((t, idx) => {
    const iso = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(String(t)) ? String(t) : t + 'Z';   // requested timezone is UTC
    const ts = Date.parse(iso);
    if (!Number.isFinite(ts) || ts > now) return;                                    // skip forecast hours
    const row = { location_id: Number(loc.id), observed_at: new Date(ts).toISOString() };
    let any = false;
    for (const m of METRICS) {
      const raw = h[m] ? h[m][idx] : null;
      if (raw === null || raw === undefined) { row[m] = null; continue; }
      const v = Number(raw);
      const [lo, hi] = LIMITS[m];
      if (!Number.isFinite(v) || v < lo || v > hi) { invalid++; row[m] = null; continue; }
      row[m] = m === 'us_aqi' ? Math.round(v) : v;
      any = true;
    }
    if (any) byKey.set(row.location_id + '|' + row.observed_at, row);
  });
});

const rows = [...byKey.values()];
return [{ json: {
  rows_json: JSON.stringify(rows),
  rows_count: rows.length,
  locations_total: locs.length,
  locations_failed: failures.length,
  rows_invalid: invalid,
  failures_text: failures.join('; ')
} }];

const rows = $input.all().map(i => i.json);
const fmt = d => new Date(d).toLocaleString('en-GB', { timeZone: 'Asia/Jakarta', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) + ' WIB';
const lines = rows.map(r => {
  const sev = String(r.severity).toUpperCase();
  if (r.alert_type === 'threshold') {
    return '[' + sev + '] ' + r.name + ': US AQI ' + Math.round(Number(r.value)) + ' (' + r.category + ') at ' + fmt(r.observed_at);
  }
  if (r.alert_type === 'spike') {
    return '[' + sev + '] ' + r.name + ': PM2.5 spike ' + Number(r.value).toFixed(1) + ' ug/m3 vs typical ' + Number(r.baseline).toFixed(1) + ' (z=' + Number(r.zscore).toFixed(1) + ') at ' + fmt(r.observed_at);
  }
  const never = new Date(r.observed_at).getFullYear() < 2000;
  return '[' + sev + '] ' + r.name + ': ' + (never ? 'no data has been ingested yet' : 'no new data since ' + fmt(r.observed_at));
});
const text = 'AIR QUALITY ALERTS (' + rows.length + ')\n\n' + lines.join('\n') +
  '\n\nModelled estimates (CAMS via Open-Meteo), not ground sensor readings.';
return [{ json: { text } }];

const t = $('Transform & Validate').first().json;
const run = $input.first().json;
let text = 'ETL WARNING: ' + t.locations_failed + ' of ' + t.locations_total + ' location(s) failed to load\n\n';
text += String(t.failures_text).split('; ').filter(Boolean).map(s => '- ' + s).join('\n');
text += '\n\nRun #' + run.run_id + ': ' + run.rows_inserted + ' inserted, ' + run.rows_updated + ' updated, ' + t.rows_invalid + ' invalid value(s) nulled.';
return [{ json: { text } }];

