WITH a AS (DELETE FROM etl_runs WHERE started_at < now() - interval '90 days' RETURNING 1),
     b AS (DELETE FROM alerts   WHERE created_at < now() - interval '180 days' RETURNING 1)
SELECT (SELECT COUNT(*)::int FROM a) AS runs_purged, (SELECT COUNT(*)::int FROM b) AS alerts_purged;

