const r = $input.first().json;
const locs = Array.isArray(r.locations) ? r.locations : [];
const day = r.day ? new Date(r.day).toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }) : 'yesterday';
let t = 'Air Quality Daily Digest\n' + day + '\n\n';
if (!locs.length) t += 'No locations are configured.\n';
else {
  t += locs.map(l => {
    if (!Number(l.hours_with_data)) return l.name + ': no data';
    return l.name + ': avg PM2.5 ' + l.avg_pm25 + ' | max ' + l.max_pm25 + ' | max AQI ' + l.max_aqi + (Number(l.hours_over) ? ' | ' + l.hours_over + ' h above alert level' : '');
  }).join('\n');
}
t += '\n\nAlerts in the last 24 h: ' + r.alerts_24h + '\nETL runs: ' + r.runs_24h + ' (' + r.runs_with_failures_24h + ' with failures)';
t += '\n\nModelled estimates (CAMS via Open-Meteo), not ground sensor readings.';
return [{ json: { text: t } }];

const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { text: 'WORKFLOW ERROR\n\nWorkflow: ' + wf + '\nFailed node: ' + node + '\nError: ' + String(msg).slice(0, 500) + (url ? '\n' + url : '') } }];
